import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        print("a: 0, e: 0, i: 0, o: 0, u: 0")
        return

    n = int(data[0].strip())
    if n == 0:
        print("a: 0, e: 0, i: 0, o: 0, u: 0")
        return

    strings = []
    for i in range(1, n + 1):
        if i < len(data):
            strings.append(data[i])
        else:
            strings.append("")

    vowels = {'a': 0, 'e': 0, 'i': 0, 'o': 0, 'u': 0}

    for s in strings:
        for char in s.lower():
            if char in vowels:
                vowels[char] += 1

    print(f"a: {vowels['a']}, e: {vowels['e']}, i: {vowels['i']}, o: {vowels['o']}, u: {vowels['u']}")

if __name__ == "__main__":
    main()
